/** Bounded physical Rack ownership, typed configuration, legacy tags and channel event proof. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeRackRuntimeChecks {
    private static ServerLevel world;private static Actor actor;private static NativeRackEntity rack;private static int ticks,checks;private static final BlockPos POS=new BlockPos(40,110,40);
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211577),"NativeRackRuntime"));}}
    private static boolean enabled(){return Boolean.getBoolean("vandorlabs.rackRuntimeChecks");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Rack tick="+ticks+": "+why);}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{world=event.getServer().overworld();world.setChunkForced(POS.getX()>>4,POS.getZ()>>4,true);world.getChunkAt(POS);world.setBlock(POS,NativeRackBindings.BLOCK.defaultBlockState(),3);rack=(NativeRackEntity)world.getBlockEntity(POS);actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);actor.setPos(40.5,110,37);data();}catch(Throwable failure){fail(failure);}}
    private static void data(){
        var legacy=new CompoundTag();var list=new ListTag();var item=new CompoundTag();item.putString("id","vandorlabs:autopilot_module");item.putByte("Count",(byte)1);item.putShort("Damage",(short)0);item.putByte("Slot",(byte)2);var custom=new CompoundTag();var state=NativeRackData.publicSettings(new AutopilotModuleSettings(ChannelList.of(31,32),2,"minecraft:wool",14));state.putString("AutopilotStatus","Retained journey");state.putLong("AutopilotDepartureAt",9123);state.putString("UnknownNavigationField","retained");custom.put(AutopilotModuleSettings.KEY,state);var cap=new CompoundTag();cap.putByteArray("Opaque",new byte[73]);custom.put("OpaqueModuleData",cap);item.put("tag",custom);list.add(item);legacy.put("Items",list);legacy.putString("RackUnknown","retained");var before=legacy.copy();var staged=new NativeRackEntity(NativeRackBindings.ENTITY,POS,rack.getBlockState());staged.loadWithComponents(legacy,world.registryAccess());need(!staged.inert()&&staged.kind(2)==2,"Source module item data accepted");need(before.equals(legacy),"Source raw input never mutated");need(NativeRackData.state(staged.module(2)).equals(state),"navigation/unknown state retained");need(NativeRackData.marker(staged.moduleSettings(2),world.registryAccess()).is(Items.RED_WOOL),"Source marker metadata uses strict existing item migration");var saved=staged.saveWithoutMetadata(world.registryAccess());var again=new NativeRackEntity(NativeRackBindings.ENTITY,POS,rack.getBlockState());again.loadWithComponents(saved,world.registryAccess());need(!again.inert()&&ItemStack.matches(staged.module(2),again.module(2)),"modern item components and private Source archive survive reload");need(saved.getString("RackUnknown").equals("retained"),"unknown rack fields retained");var publicTag=staged.getUpdateTag(world.registryAccess());need(!publicTag.contains("Items")&&!publicTag.contains("OpaqueModuleData")&&!publicTag.contains("RackUnknown")&&!publicTag.toString().contains("UnknownNavigationField"),"public update has typed choices only");var malformed=before.copy();malformed.getList("Items",Tag.TAG_COMPOUND).add(item.copy());var bad=new NativeRackEntity(NativeRackBindings.ENTITY,POS,rack.getBlockState());bad.loadWithComponents(malformed,world.registryAccess());need(bad.inert()&&bad.ownedModuleDrops().isEmpty(),"ambiguous duplicate slots remain inert");var preserved=bad.saveWithoutMetadata(world.registryAccess());for(String key:malformed.getAllKeys())need(Objects.equals(malformed.get(key),preserved.get(key)),"failed original field retained "+key);
    }
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!enabled()||world==null)return;try{if(++ticks==2){
        need(rack.configure(-1,true,new NativeRackData.Transmission(ChannelList.of(41001),16,true,true)),"installed standard transmission choices");
        for(int slot=0;slot<4;slot++){var stack=new ItemStack(slot==2?NativeRackBindings.AUTOPILOT:NativeRackBindings.BLANK);need(rack.insert(slot,stack,false)&&stack.isEmpty(),"physical insertion consumes exactly one "+slot);need(rack.output.localSignalLevel(0)==ModuleRackPolicy.signalLevel((1<<(slot+1))-1),"proportional standard output "+slot);}
        need(!((Object)rack instanceof net.minecraft.world.Container),"internal bays expose no automation inventory");
        need(rack.configureModule(2,rack.sequence(2),new AutopilotModuleSettings(ChannelList.of(41002),1,"minecraft:red_wool",0)),"independent module receive settings");
        var sourcePos=POS.west(2);world.setBlock(sourcePos,NativeRackBindings.BLOCK.defaultBlockState(),3);var source=(NativeRackEntity)world.getBlockEntity(sourcePos);for(int slot=0;slot<4;slot++)need(source.insert(slot,new ItemStack(NativeRackBindings.BLANK),false),"physical output-source module");need(source.configure(-1,true,new NativeRackData.Transmission(ChannelList.of(41002),16,true,true)),"standard Rack wireless source");NativeRedstoneChannels.flush(world);
        var runtime=NativeRackData.state(rack.module(2));need(runtime.getBoolean("AutopilotEnabled")&&runtime.getBoolean("AutopilotHigh"),"actual standard channel delivery reaches per-module receiver");need(runtime.getString("AutopilotStatus").contains("not available"),"unsupported native Vehicle navigation is explicit");
        var removed=rack.extract(1);need(!removed.isEmpty()&&rack.output.localSignalLevel(0)==11,"extraction updates proportional output");need(rack.insert(1,removed,false)&&removed.isEmpty(),"reinsertion retains one physical owner");
        menu();persistence();long writes=rack.serialized;for(int sample=0;sample<1000;sample++){rack.visual();rack.getModelData();}need(writes==rack.serialized,"model lookup does not serialize module inventory");
        need(rack.drain().size()==4&&rack.occupied()==0&&rack.drain().isEmpty(),"mining drain transfers four modules once");System.out.println("[vandorlabs][rack-runtime] PASS checks="+checks+" SourceNBT/components/privateAppearance/realChannels/proportionalOutputs/menuAuth/typedCodec/oneOwner");world=null;event.getServer().halt(false);
    }else need(ticks<80,"bounded runtime fixture");}catch(Throwable failure){fail(failure);}}
    private static void menu(){var menu=new NativeRackMenu(NativeRackBindings.MENU,73,rack);actor.containerMenu=menu;var next=new AutopilotModuleSettings(ChannelList.of(8,9),2,"minecraft:blue_wool",0);long sequence=rack.sequence(2);need(menu.configureModule(actor,73,POS,2,sequence,next),"exact window/member module settings");need(!menu.configureModule(actor,72,POS,2,sequence,next),"wrong window rejected");need(!menu.configureModule(actor,73,POS,2,sequence+1,next),"stale module sequence rejected");need(!menu.configureModule(actor,73,POS,2,sequence,new AutopilotModuleSettings(ChannelList.EMPTY,1,"missing:marker",0)),"unregistered new route marker rejected");var buffer=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());try{var packet=NativeRackSettingsPayload.module(73,POS,2,sequence,next);NativeRackSettingsPayload.CODEC.encode(buffer,packet);need(buffer.readableBytes()<80,"bounded choices packet");need(NativeRackSettingsPayload.CODEC.decode(buffer).module().equals(next),"typed choices wire round trip");buffer.clear();NativeRackSettingsPayload.CODEC.encode(buffer,packet);buffer.setByte(22,65);boolean refused=false;try{NativeRackSettingsPayload.CODEC.decode(buffer);}catch(RuntimeException expected){refused=true;}need(refused,"channel allocation bound before decode");buffer.clear();NativeRackSettingsPayload.CODEC.encode(buffer,NativeRackSettingsPayload.housing(73,POS,-1,false,NativeRackData.Transmission.fresh()));buffer.setByte(17,2);refused=false;try{NativeRackSettingsPayload.CODEC.decode(buffer);}catch(RuntimeException expected){refused=true;}need(refused,"noncanonical boolean refused");}finally{buffer.release();}actor.containerMenu=actor.inventoryMenu;need(!menu.configureModule(actor,73,POS,2,sequence,next),"closed dialog cannot mutate");}
    private static void persistence(){
        var blank=rack.extract(0);var other=new ItemStack(NativeRackBindings.AUTOPILOT);var independent=new AutopilotModuleSettings(ChannelList.of(19),1,"minecraft:orange_wool",0);NativeRackData.configure(other,independent);need(rack.insert(0,other,false),"second distinct Autopilot installed");
        var previousHousing=rack.housing();var previousEmit=rack.emits();var previousOutput=rack.transmission();
        var item=rack.extract(2);var state=NativeRackData.state(item);state.putInt("AutopilotDepartureHeight",37);state.putInt("AutopilotDepartureMode",2);state.putBoolean("AutopilotDepartureDirect",false);state.putString("ForeignNavigationLimits","retained");NativeRackData.state(item,state);var opaque=NativeRackData.data(item);opaque.putString("OpaqueItem","first-module-only");item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(opaque));need(rack.insert(2,item,false),"module limit fixture reinsert");
        var next=new AutopilotModuleSettings(ChannelList.of(11,73),2,"minecraft:lime_wool",0);var menu=new NativeRackMenu(NativeRackBindings.MENU,81,rack);actor.containerMenu=menu;
        need(menu.configureModule(actor,81,POS,2,rack.sequence(2),next),"mounted exact editor route writes physical module");
        item=rack.extract(2); // No tick or host serialization after editor commit.
        need(NativeRackData.settings(item).equals(next),"immediate extraction retains route/activation/channels");state=NativeRackData.state(item);
        need(state.getInt("AutopilotDepartureHeight")==37&&state.getInt("AutopilotDepartureMode")==2&&!state.getBoolean("AutopilotDepartureDirect")&&state.getString("ForeignNavigationLimits").equals("retained"),"limits and opaque fields remain module-owned");
        need(rack.moduleSettings(0).equals(independent)&&NativeRackData.data(item).getString("OpaqueItem").equals("first-module-only"),"other Autopilot unchanged and extracted opaque data retained");
        need(rack.housing()==previousHousing&&rack.emits()==previousEmit&&rack.transmission().equals(previousOutput),"Rack housing/output unaffected by module edit/extraction");
        need(rack.insert(2,item,false),"edited item reinserts after extraction");var saved=rack.saveWithoutMetadata(world.registryAccess());var loaded=new NativeRackEntity(NativeRackBindings.ENTITY,POS,rack.getBlockState());loaded.loadWithComponents(saved,world.registryAccess());
        need(!loaded.inert()&&NativeRackData.settings(loaded.module(2)).equals(next)&&NativeRackData.state(loaded.module(2)).getString("ForeignNavigationLimits").equals("retained"),"module choices/opaque limits survive reinsert+reload");
        need(loaded.moduleSettings(0).equals(independent)&&NativeRackData.data(loaded.module(2)).getString("OpaqueItem").equals("first-module-only"),"both distinct module settings and opaque item data survive reload");
        need(loaded.housing()==previousHousing&&loaded.emits()==previousEmit&&loaded.transmission().equals(previousOutput),"Rack own settings separately survive reload");rack.extract(0);need(rack.insert(0,blank,false),"restore blank bay after two-module persistence proof");actor.containerMenu=actor.inventoryMenu;
    }
    private static void fail(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][rack-runtime] FAIL "+failure);var server=world==null?net.neoforged.neoforge.server.ServerLifecycleHooks.getCurrentServer():world.getServer();world=null;if(server!=null)server.halt(false);}
}
